const src = $json || {};
const baseText = String(src.text || '').trim();
const sentryProject = String(src.project || '').toLowerCase();
let projects = [];
try {
  const parsed = JSON.parse(String($env.PROJECTS_CONFIG || '{"projects":[]}'));
  projects = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.projects) ? parsed.projects : []);
} catch {
  projects = [];
}
const match = projects.find((p) => {
  const key = String(p?.key || '').toLowerCase();
  const label = String(p?.label || '').toLowerCase();
  const sentryLink = String(p?.links?.sentry || '').toLowerCase();
  if (!sentryProject) return false;
  return key === sentryProject || label.includes(sentryProject) || sentryLink.includes(sentryProject);
}) || (projects.length === 1 ? projects[0] : null);
const label = String(match?.label || match?.key || '').trim();
const prefix = label ? ('[' + label + '] ') : '';
const text = baseText.startsWith('[') ? baseText : (prefix + baseText);
const rawThread = match?.telegramThreadId;
const threadId = rawThread === undefined || rawThread === null || String(rawThread).trim() === '' ? undefined : Number(rawThread);
return [{ json: { ...src, text, threadId } }];

const err = $json.error || null;
if (!err) return [{ json: { telegramFailed: false } }];
const status = Number(err.statusCode ?? err.status ?? err.httpCode ?? err.code ?? 0);
const body = err.responseBody ?? err.body ?? err.data ?? '';
const detail = (typeof err.message === 'string' && err.message)
  || (typeof err.description === 'string' && err.description)
  || (typeof body === 'string' ? body : JSON.stringify(body))
  || JSON.stringify(err);
const msg = String(detail).slice(0, 360);
const rateLimited = status === 429 || /429|rate\s*limit|too many requests/i.test(String(status) + ' ' + msg);
return [{ json: { telegramFailed: true, rateLimited, reason: msg } }];
